    public static void zd_enc_DDS_XTypes_CompleteTypeObject(Writer w, ZdTypes.DDS.XTypes.CompleteTypeObject v) {
        Writer.DHeader d = Writer.noDheader();
        zd_enc_p_octet(w, v._d);
        if (v._d == (byte) 48) {
            zd_enc_DDS_XTypes_CompleteAliasType(w, v.alias_type);
        } else {
            if (v._d == (byte) 80) {
                zd_enc_DDS_XTypes_CompleteAnnotationType(w, v.annotation_type);
            } else {
                if (v._d == (byte) 81) {
                    zd_enc_DDS_XTypes_CompleteStructType(w, v.struct_type);
                } else {
                    if (v._d == (byte) 82) {
                        zd_enc_DDS_XTypes_CompleteUnionType(w, v.union_type);
                    } else {
                        if (v._d == (byte) 83) {
                            zd_enc_DDS_XTypes_CompleteBitsetType(w, v.bitset_type);
                        } else {
                            if (v._d == (byte) 96) {
                                zd_enc_DDS_XTypes_CompleteSequenceType(w, v.sequence_type);
                            } else {
                                if (v._d == (byte) 97) {
                                    zd_enc_DDS_XTypes_CompleteArrayType(w, v.array_type);
                                } else {
                                    if (v._d == (byte) 98) {
                                        zd_enc_DDS_XTypes_CompleteMapType(w, v.map_type);
                                    } else {
                                        if (v._d == (byte) 64) {
                                            zd_enc_DDS_XTypes_CompleteEnumeratedType(w, v.enumerated_type);
                                        } else {
                                            if (v._d == (byte) 65) {
                                                zd_enc_DDS_XTypes_CompleteBitmaskType(w, v.bitmask_type);
                                            } else {
                                                zd_enc_DDS_XTypes_CompleteExtendedType(w, v.extended_type);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        w.finishDheader(d);
    }

